CREATE PROCEDURE "TNX_AllItemsList"()
As
Begin

SELECT T0."BcdCode",  T0."ItemCode", Case when IFNULL(T0."BcdName",'')='' THEN T1."ItemName" ELSE  IFNULL(T0."BcdName",'') END as "ItemName" ,T5."ItmsGrpNam",T1."U_VSubGroup",T1."U_VSubSubGroup",T1."U_VSubSubSubGroup", T1."CardCode",T6."CardName",T1."U_BRAND",T1."VatGourpSa", T1."VatGroupPu", T1."CreateDate" as "Create Date", T1."UpdateDate",  T2."UomCode", 
(Case When T3."BaseUom" = T0."UomEntry" Then 'Yes' Else 'No' End) as "BaseUom",
T4."AltQty", T4."BaseQty",T1."LastPurPrc",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='1' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='1'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='1' and "UomEntry"=T0."UomEntry"),0) end) as "HO RSP",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='2' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='2'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='2' and "UomEntry"=T0."UomEntry"),0) end) as "Al Rigga1 RSP", 
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='3' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='3'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='3' and "UomEntry"=T0."UomEntry"),0) end) as "Al Rigga2 RSP",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='4' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='4'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='4' and "UomEntry"=T0."UomEntry"),0) end) as "Al Rigga3 RSP",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='5' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='5'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='5' and "UomEntry"=T0."UomEntry"),0) end) as "Al Rigga4 RSP",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='6' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='6'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='6' and "UomEntry"=T0."UomEntry"),0) end) as "Al MQBT1 RSP",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='7' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='7'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='7' and "UomEntry"=T0."UomEntry"),0) end) as "Al MQBT2 RSP",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='8' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='8'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='8' and "UomEntry"=T0."UomEntry"),0) end) as "Al MQBT3 RSP",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='9' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='9'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='9' and "UomEntry"=T0."UomEntry"),0) end) as "Salahuddin RSP",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='10' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='10'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='10' and "UomEntry"=T0."UomEntry"),0) end) as "Al Bada RSP",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='11' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='11'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='11' and "UomEntry"=T0."UomEntry"),0) end) as "Diyafah1 RSP",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='12' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='12'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='12' and "UomEntry"=T0."UomEntry"),0) end) as "Diyafah2 RSP",
(Case when  ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='13' and "UomEntry"=T0."UomEntry"),0)=0  then ifnull((Select "Price" from ITM9 where "ItemCode"=T0."ItemCode" and "UomEntry"=T0."UomEntry" and "PriceList"='13'),0) else ifnull((Select "Price" from ITM1 where "ItemCode"=T0."ItemCode" and "PriceList"='13' and "UomEntry"=T0."UomEntry"),0) end) as "Purchase PriceList"

 FROM OBCD T0  INNER JOIN OITM T1 ON T0."ItemCode" = T1."ItemCode" INNER JOIN OUOM T2 ON T0."UomEntry" = T2."UomEntry" INNER JOIN OUGP T3 ON T1."UgpEntry" = T3."UgpEntry" INNER JOIN UGP1 T4 ON T3."UgpEntry" = T4."UgpEntry" AND T4."UomEntry"=T0."UomEntry" INNER JOIN OITB T5 ON T1."ItmsGrpCod" = T5."ItmsGrpCod" Left join OCRD T6 on T6."CardCode"=T1."CardCode" 

ORDER BY T1."ItemCode" ASC, (Case When T3."BaseUom" = T0."UomEntry" Then 'Yes' Else 'No' End) DESC;
END;